/**
 * kpai-harness-contract.test.ts — schema contract over the KPAI harness proof artifact.
 *
 * Subject: `.kpai-harness-verified.json` at the repository root, generated by
 * `scripts/test-kpai-harness.sh --emit`.
 *
 * This file asserts the artifact's SHAPE and VALUES. It deliberately does not run
 * the generator — `kpai-harness-execution.test.ts` owns that half. Splitting them
 * means a broken generator and a malformed artifact produce different red tests.
 *
 * Path resolution uses `import.meta.dir`, never `process.cwd()`. Under this
 * harness the shell tool's cwd can be a different worktree entirely, and a
 * cwd-relative read would silently assert against another agent's artifact.
 *
 * Run: bun test test/unit/kpai-harness-contract.test.ts
 *
 * @id     kpai-harness-contract-test
 * @target .kpai-harness-verified.json
 * @doc    docs/kpai-harness-verification.md
 * @task   KTEST-P1-1
 */

import { describe, expect, test } from "bun:test";
import { existsSync, readFileSync, statSync } from "node:fs";
import { isAbsolute, resolve } from "node:path";

const REPO_ROOT = resolve(import.meta.dir, "..", "..");
const ARTIFACT_PATH = resolve(REPO_ROOT, ".kpai-harness-verified.json");

const SCHEMA_ID = "kpai-harness-verification/v1";
const TASK_ID = "KTEST-P1-1";
const AGENT_ID = "kpai";
const BASE_REF = "integration/crkc-v0.1.0";
const PRINCIPAL_CHECKOUT = "/home/andy/src/cp/osramp-demo";

const SHA1_RE = /^[0-9a-f]{40}$/;
const SHA256_RE = /^[0-9a-f]{64}$/;
const SEMVER_PREFIX_RE = /^\d+\.\d+\.\d+/;
const ISO_OFFSET_RE = /(Z|[+-]\d{2}:?\d{2})$/;

interface HarnessCheck {
  id: string;
  name: string;
  status: string;
  detail: string;
}

interface HarnessArtifact {
  schema: string;
  task_id: string;
  agent: string;
  generated_at: string;
  generator: string;
  runtime: { bun: string; bash: string; git: string; kernel: string };
  worktree: {
    root: string;
    real_root: string;
    head: string;
    branch: string;
    base_ref: string;
    derives_from_base_ref: boolean;
    is_linked_worktree: boolean;
    is_principal_checkout: boolean;
    principal_checkout: string;
    dirty_entries: number;
  };
  sandbox: {
    no_new_privs: number;
    landlock_available: boolean;
    nono_cap_file: string;
    worktree_writable: boolean;
    denial_indistinguishable_from_absence: boolean;
    caveat: string;
  };
  canary: { path: string; digest: string; deterministic: boolean };
  checks: HarnessCheck[];
  summary: { declared: number; total: number; passed: number; failed: number };
}

// Read once. A parse failure here should surface as a single obvious red test
// rather than 30 confusing ones, so existence and parseability are asserted
// first and the rest of the suite reads the already-parsed object.
const raw = existsSync(ARTIFACT_PATH) ? readFileSync(ARTIFACT_PATH, "utf8") : "";
let parsed: HarnessArtifact | null = null;
let parseError: string | null = null;
try {
  parsed = JSON.parse(raw) as HarnessArtifact;
} catch (err) {
  parseError = err instanceof Error ? err.message : String(err);
}

function artifact(): HarnessArtifact {
  if (parsed === null) {
    throw new Error(`artifact unparsed: ${parseError ?? "not read"}`);
  }
  return parsed;
}

describe("artifact presence and parseability", () => {
  test("ISC-36a: the artifact exists at the repository root", () => {
    expect(existsSync(ARTIFACT_PATH)).toBe(true);
  });

  test("ISC-36b: the artifact parses as JSON", () => {
    expect(parseError).toBeNull();
    expect(parsed).not.toBeNull();
  });

  test("ISC-36c: the artifact is a JSON object, not an array or scalar", () => {
    const a = artifact() as unknown;
    expect(typeof a).toBe("object");
    expect(Array.isArray(a)).toBe(false);
  });
});

describe("identity fields", () => {
  test("ISC-37: schema is the pinned contract id", () => {
    expect(artifact().schema).toBe(SCHEMA_ID);
  });

  test("ISC-38: agent is kpai", () => {
    expect(artifact().agent).toBe(AGENT_ID);
  });

  test("ISC-39: task_id is the full namespaced card id", () => {
    expect(artifact().task_id).toBe(TASK_ID);
  });

  test("ISC-40a: generated_at parses as a Date", () => {
    const t = Date.parse(artifact().generated_at);
    expect(Number.isNaN(t)).toBe(false);
  });

  test("ISC-40b: generated_at carries a UTC Z or numeric offset suffix", () => {
    // A bare local timestamp is ambiguous across machines and would make the
    // artifact non-comparable between a laptop and the CI VM.
    expect(artifact().generated_at).toMatch(ISO_OFFSET_RE);
  });

  test("generator names the script that produced this artifact", () => {
    expect(artifact().generator).toBe("scripts/test-kpai-harness.sh");
  });
});

describe("runtime telemetry", () => {
  test("bun version is semver-shaped", () => {
    expect(artifact().runtime.bun).toMatch(SEMVER_PREFIX_RE);
  });

  test("bash version is recorded and non-empty", () => {
    expect(artifact().runtime.bash.length).toBeGreaterThan(0);
  });

  test("git version string is git's own format", () => {
    expect(artifact().runtime.git).toMatch(/^git version \d/);
  });

  test("kernel is recorded and non-empty", () => {
    expect(artifact().runtime.kernel.length).toBeGreaterThan(0);
  });
});

describe("worktree lineage and isolation", () => {
  test("root is an absolute path", () => {
    expect(isAbsolute(artifact().worktree.root)).toBe(true);
  });

  test("head is a 40-character hexadecimal SHA", () => {
    expect(artifact().worktree.head).toMatch(SHA1_RE);
  });

  test("base_ref is the CRKC integration branch", () => {
    expect(artifact().worktree.base_ref).toBe(BASE_REF);
  });

  test("ISC-42: HEAD derives from the base ref", () => {
    expect(artifact().worktree.derives_from_base_ref).toBe(true);
  });

  test("ISC-41: this is not the principal checkout", () => {
    expect(artifact().worktree.is_principal_checkout).toBe(false);
  });

  test("ISC-41b: root is not literally the principal checkout path", () => {
    // Belt and braces: the boolean above is computed by the script, this asserts
    // the recorded path independently so a flag flipped by hand cannot pass both.
    expect(artifact().worktree.root).not.toBe(PRINCIPAL_CHECKOUT);
    expect(artifact().worktree.real_root).not.toBe(PRINCIPAL_CHECKOUT);
  });

  test("this is a linked worktree, not a clone", () => {
    expect(artifact().worktree.is_linked_worktree).toBe(true);
  });

  test("dirty_entries is a non-negative integer", () => {
    const n = artifact().worktree.dirty_entries;
    expect(Number.isInteger(n)).toBe(true);
    expect(n).toBeGreaterThanOrEqual(0);
  });
});

describe("sandbox posture", () => {
  test("ISC-43a: NoNewPrivs is 1 — the process cannot elevate privilege", () => {
    expect(artifact().sandbox.no_new_privs).toBe(1);
  });

  test("ISC-43b: Landlock is an active LSM", () => {
    expect(artifact().sandbox.landlock_available).toBe(true);
  });

  test("the nono capability file is recorded", () => {
    expect(artifact().sandbox.nono_cap_file.length).toBeGreaterThan(0);
  });

  test("the worktree is writable despite confinement", () => {
    expect(artifact().sandbox.worktree_writable).toBe(true);
  });

  test("ISC-16: the denial-vs-absence caveat is a field, not just prose", () => {
    // This is the whole point of recording it structurally: a reader consuming
    // the artifact programmatically must be forced to see that an absent result
    // is absence-as-observed, not proven non-existence.
    expect(artifact().sandbox.denial_indistinguishable_from_absence).toBe(true);
    expect(artifact().sandbox.caveat).toContain("byte-identical");
  });
});

describe("canary block", () => {
  test("canary path is absolute", () => {
    expect(isAbsolute(artifact().canary.path)).toBe(true);
  });

  test("canary digest is a SHA-256 hex digest", () => {
    expect(artifact().canary.digest).toMatch(SHA256_RE);
  });

  test("canary is declared deterministic", () => {
    expect(artifact().canary.deterministic).toBe(true);
  });
});

describe("checks array", () => {
  test("ISC-44a: checks is a non-empty array", () => {
    expect(Array.isArray(artifact().checks)).toBe(true);
    expect(artifact().checks.length).toBeGreaterThan(0);
  });

  test("ISC-44b: every check has id, name, status and detail, all strings", () => {
    for (const c of artifact().checks) {
      expect(typeof c.id).toBe("string");
      expect(typeof c.name).toBe("string");
      expect(typeof c.status).toBe("string");
      expect(typeof c.detail).toBe("string");
      expect(c.id.length).toBeGreaterThan(0);
      expect(c.name.length).toBeGreaterThan(0);
    }
  });

  test("ISC-45: every check passed", () => {
    const failed = artifact().checks.filter((c) => c.status !== "pass");
    expect(failed.map((c) => `${c.id}:${c.name}:${c.detail}`)).toEqual([]);
  });

  test("ISC-47: check ids are unique", () => {
    const ids = artifact().checks.map((c) => c.id);
    expect(new Set(ids).size).toBe(ids.length);
  });

  test("check status is drawn from the closed pass/fail vocabulary", () => {
    for (const c of artifact().checks) {
      expect(["pass", "fail"]).toContain(c.status);
    }
  });
});

describe("summary consistency", () => {
  test("ISC-46a: summary.total equals the number of checks recorded", () => {
    expect(artifact().summary.total).toBe(artifact().checks.length);
  });

  test("ISC-46b: summary.failed is zero", () => {
    expect(artifact().summary.failed).toBe(0);
  });

  test("ISC-35: summary.declared equals summary.total — no probe silently skipped", () => {
    // The defect this pins: a suite that ran fewer probes than it defines exits 0
    // and reads exactly like a suite that passed. The declared/total identity is
    // the only thing that distinguishes them.
    expect(artifact().summary.declared).toBe(artifact().summary.total);
  });

  test("passed and failed partition the total", () => {
    const s = artifact().summary;
    expect(s.passed + s.failed).toBe(s.total);
  });

  test("passed equals the count of pass-status checks", () => {
    const passing = artifact().checks.filter((c) => c.status === "pass").length;
    expect(artifact().summary.passed).toBe(passing);
  });
});

// ---------------------------------------------------------------------------
// Cross-checks against freshly measured reality.
//
// Everything above this line asserts that the artifact is internally consistent.
// That is necessary and not sufficient: a committed artifact keeps passing those
// assertions forever, on any machine, including one with no Landlock, no nono,
// a different bun and no worktree. The suite would then be asserting "this JSON
// is well-formed", not "this harness is capable" -- which is the actual claim.
//
// So each environment fact recorded in the artifact is re-measured HERE, at test
// time, and compared. If the two disagree, the artifact does not describe the
// machine running the test, and that is a real finding rather than a flaky test:
// it means the harness changed, or the artifact was generated somewhere else.
// ---------------------------------------------------------------------------

const SCRIPT_PATH = resolve(REPO_ROOT, "scripts", "test-kpai-harness.sh");

function capture(cmd: string[]): string {
  const proc = Bun.spawnSync({ cmd, cwd: REPO_ROOT, stdout: "pipe", stderr: "pipe" });
  return new TextDecoder().decode(proc.stdout).trim();
}

function spawnCode(cmd: string[]): number {
  const proc = Bun.spawnSync({ cmd, cwd: REPO_ROOT, stdout: "pipe", stderr: "pipe" });
  return proc.exitCode ?? -1;
}

function readOrEmpty(path: string): string {
  return existsSync(path) ? readFileSync(path, "utf8") : "";
}

describe("cross-check: artifact values versus live measurement", () => {
  test("recorded bun version equals the bun actually running this test", () => {
    expect(artifact().runtime.bun).toBe(Bun.version);
  });

  test("recorded git version equals the git on this PATH", () => {
    expect(artifact().runtime.git).toBe(capture(["git", "--version"]));
  });

  test("recorded bash version equals this machine's bash", () => {
    const live = capture(["bash", "-c", "printf %s \"$BASH_VERSION\""]);
    expect(artifact().runtime.bash).toBe(live);
  });

  test("recorded kernel equals `uname -sr` now", () => {
    expect(artifact().runtime.kernel).toBe(capture(["uname", "-sr"]));
  });

  test("recorded NoNewPrivs equals /proc/self/status right now", () => {
    const live = readOrEmpty("/proc/self/status").match(/^NoNewPrivs:\s*(\d+)$/m)?.[1];
    expect(live).toBeDefined();
    expect(artifact().sandbox.no_new_privs).toBe(Number(live));
  });

  test("recorded Landlock availability equals the live LSM list", () => {
    const lsm = readOrEmpty("/sys/kernel/security/lsm").trim();
    const live = lsm.split(",").includes("landlock");
    expect(artifact().sandbox.landlock_available).toBe(live);
  });

  test("recorded nono capability file equals the live NONO_CAP_FILE", () => {
    // If this fails, the tests are running outside the nono profile the artifact
    // was generated under. That is a genuine difference in harness, not a flake.
    expect(artifact().sandbox.nono_cap_file).toBe(process.env.NONO_CAP_FILE ?? "");
  });

  test("recorded worktree root is this repository", () => {
    expect(artifact().worktree.root).toBe(capture(["git", "rev-parse", "--show-toplevel"]));
  });

  test("recorded HEAD is an ancestor of (or equal to) the current HEAD", () => {
    // Deliberately NOT equality. The artifact is generated before the commit that
    // adds it, so its HEAD is one commit behind from the moment it lands. The
    // ancestor relation is the invariant that survives: it stays true for every
    // later commit on this branch, and fails if the artifact came from an
    // unrelated tree -- which is the case worth catching.
    expect(spawnCode(["git", "merge-base", "--is-ancestor", artifact().worktree.head, "HEAD"])).toBe(0);
  });

  test("recorded base-ref lineage still holds when re-checked live", () => {
    const code = spawnCode(["git", "merge-base", "--is-ancestor", artifact().worktree.base_ref, "HEAD"]);
    expect(artifact().worktree.derives_from_base_ref).toBe(code === 0);
  });

  test("the canary digest re-derives from the recorded HEAD", () => {
    const expected = new Bun.CryptoHasher("sha256")
      .update(`kpai-harness-canary|v1|${artifact().worktree.head}`)
      .digest("hex");
    expect(artifact().canary.digest).toBe(expected);
  });

  test("recorded declared-probe count equals the constant in the generator", () => {
    // Closes the loop the other way: if someone edits DECLARED_PROBES in the
    // script without regenerating, the artifact and the script disagree.
    const declared = readOrEmpty(SCRIPT_PATH).match(/readonly DECLARED_PROBES=(\d+)/)?.[1];
    expect(declared).toBeDefined();
    expect(artifact().summary.declared).toBe(Number(declared));
  });
});

describe("artifact freshness", () => {
  test("both the artifact and its generator exist", () => {
    // Asserted separately and first, because a missing file makes a naive mtime
    // comparison degrade into a bare existence check that silently passes.
    expect(existsSync(ARTIFACT_PATH)).toBe(true);
    expect(existsSync(SCRIPT_PATH)).toBe(true);
  });

  test("the artifact is not older than the generator that produced it", () => {
    const artifactMtime = statSync(ARTIFACT_PATH).mtimeMs;
    const scriptMtime = statSync(SCRIPT_PATH).mtimeMs;
    expect(artifactMtime).toBeGreaterThanOrEqual(scriptMtime);
  });
});
